def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            pre_key = (1,)  # no prerelease sorts after any prerelease
        else:
            idents = pre.split('.')
            parts = []
            for ident in idents:
                if ident.isdigit():
                    parts.append((0, int(ident)))
                else:
                    parts.append((1, ident))
            pre_key = (0, len(parts), parts)
        return (major, minor, patch, pre_key)

    return sorted(versions, key=parse)

